-- ============================================
-- AI关键词话术库数据插入脚本
-- 覆盖常见情绪和心理话题的精准回复
-- ============================================

SET NAMES utf8mb4;

USE see_you;

DELETE FROM psy_ai_words;

INSERT INTO psy_ai_words (keyword, reply_text, sort) VALUES
('自杀', '我听到你说到这些，我真的很担心你。你的生命很珍贵，值得被好好对待。如果你现在有伤害自己的想法，请一定寻求专业帮助：\n\n全国心理援助热线：\n- 北京：010-82951332\n- 上海：021-12320-5\n- 全国24小时：400-161-9995\n- 生命热线：400-821-1215\n\n如果情况紧急，请立即拨打120或前往最近的医院急诊科。\n\n你不是一个人，有很多人愿意帮助你。我们慢慢来，我在这里陪着你。', 1),
('自残', '我听到你提到这些，我能感受到你正在经历很大的痛苦。自我伤害虽然能暂时缓解情绪，但它不能解决根本问题，反而可能让你更受伤。\n\n我想让你知道：\n1. 有这种感觉不是你的错\n2. 有很多健康的方式来处理痛苦（比如深呼吸、运动、找人倾诉）\n3. 专业的心理咨询师可以帮助你找到更好的应对方式\n\n你愿意和我多说说是什么让你感到这么痛苦吗？', 2),
('焦虑', '焦虑是一种很正常的情绪，每个人都会有。但如果焦虑已经影响到你的日常生活，那可能需要关注一下。\n\n给你几个小建议：\n- 试着做几次深呼吸，吸气4秒，屏住4秒，呼气6秒\n- 把担心的事情写下来，你会发现很多担忧其实不会发生\n- 试试渐进式肌肉放松法，从脚到头依次绷紧再放松肌肉\n\n如果焦虑持续严重，建议做一次「GAD-7 广泛性焦虑量表」测评，我可以帮你分析结果。', 3),
('抑郁', '抑郁情绪就像是心里的天气持续阴沉，这不是你的错，也不是因为你不够坚强。\n\n如果你感到持续的情绪低落，我建议你先做一个「PHQ-9 抑郁筛查量表」，它能帮助你更客观地了解自己的状态。\n\n同时，这些小事可能会让你感觉好一点：\n- 每天出门晒10分钟太阳\n- 尝试做一件让自己开心的小事，哪怕很小\n- 和朋友或家人聊聊，不需要强迫自己笑\n\n你愿意说说最近发生了什么吗？', 4),
('压力大', '压力太大的时候，身体和心理都会发出信号。你的肩膀紧绷吗？睡眠还好吗？\n\n几个减压小技巧：\n1. 4-7-8呼吸法：吸气4秒，屏住7秒，呼气8秒\n2. 5分钟正念冥想，只关注当下的一呼一吸\n3. 把任务列出来，一次只做一件最重要的事\n4. 允许自己休息，休息不是浪费时间\n\n如果压力已经让你身心俱疲，可以试试「PSS-10 压力感知量表」看看你的压力水平。', 5),
('失眠', '失眠真的很痛苦，明明很累了却睡不着。\n\n一些帮助入睡的方法：\n- 睡前1小时不看手机，蓝光会抑制褪黑素分泌\n- 建立固定的睡前仪式（泡脚、拉伸、听轻音乐）\n- 如果20分钟还没睡着，起床做点轻松的事，等有困意再回床\n- 下午2点后不喝咖啡/茶\n\n如果长期失眠，建议做「ISI 失眠严重程度量表」和「PSQI 匹兹堡睡眠质量指数」测评。你的睡眠问题持续多久了？', 6),
('睡不着', '数羊有时候反而让人更清醒。试试这些方法：\n\n1. 身体扫描：从头顶到脚底，依次感受每个部位是否放松\n2. 想象一个让你安心的场景（比如海边、森林）\n3. 如果脑子里有很多想法，起床写在纸上，告诉自己"明天再处理"\n4. 保持卧室温度在18-22度之间\n\n你平时几点上床？一般躺多久能睡着？', 7),
('难过', '抱抱你 🤗 难过的时候就允许自己难过吧，不需要急着"好起来"。\n\n你可以试试：\n- 找一个安静的地方哭出来，眼泪能释放压力激素\n- 听一首符合心情的歌，让情绪流动\n- 写下来："我现在难过是因为..."\n- 如果愿意，可以写篇日记然后发给AI，我陪你一起梳理\n\n你想说说发生了什么吗？或者就这样安静待一会儿也很好。', 8),
('伤心', '伤心是一种很真实的感受，不要急着否定它。你的心在告诉你，某些事情对你很重要。\n\n允许自己伤心一会儿：\n- 找个舒服的地方坐下，感受这种情绪在身体哪里\n- 对自己说："我现在很伤心，这是正常的"\n- 回忆一下过去你是如何走出类似情绪的\n\n如果你想倾诉，我一直在这里。如果你不想说话，沉默也是一种陪伴。', 9),
('孤独', '孤独是一种很普遍的感受，很多人都有，只是很少被说出来。\n\n孤独不一定是因为身边没人，有时候是心里缺乏被理解的感觉。\n\n一些建议：\n- 主动联系一个老朋友，哪怕只是发一条消息\n- 尝试做志愿者或加入兴趣小组，建立弱连接也很有意义\n- 养一只宠物，或者照顾一盆植物\n- 做一次「UCLA 孤独量表」测评，看看你的孤独感程度\n\n现在愿意和我说说你的感受吗？', 10),
('失恋', '失恋真的很痛，就像心里缺了一块。这种痛是真实的，不需要急着"走出来"。\n\n给失恋中的你：\n1. 允许自己 grieving（哀悼），这是治愈的一部分\n2. 不要急着删除回忆，给自己一点时间\n3. 多和朋友在一起，哪怕不说话\n4. 暂时避免看对方的社交媒体\n5. 每天做一件让自己开心的小事\n\n时间会帮你，但愈合的过程需要被尊重。你现在最想做什么？', 11),
('工作', '工作确实会消耗我们很多精力。你是在为工作本身烦恼，还是工作中的人际关系让你疲惫？\n\n工作中的情绪急救：\n- 设定"工作边界"，下班后尽量不处理工作消息\n- 每天列3个最重要的任务，完成就给自己点赞\n- 和同事建立支持性关系，哪怕只是偶尔一起吃午饭\n- 如果工作让你长期痛苦，也许是时候思考：这份工作是否还适合你？\n\n工作是生活的一部分，但不是全部。你现在最想改变工作中的什么？', 12),
('学习', '学习压力大的时候，我们容易自我批评。但有时候"学不进去"恰恰是因为太累了，大脑需要休息。\n\n缓解学习压力：\n- 番茄工作法：学习25分钟，休息5分钟\n- 把大目标拆成小目标，每完成一个就奖励自己\n- 保证睡眠！熬夜学习效率其实很低\n- 如果焦虑严重，试试「焦虑自评量表SAS」\n\n你现在是在准备考试还是长期的学习压力？', 13),
('家庭', '家庭关系是最复杂的，因为爱与期待常常纠缠在一起。\n\n和家人相处困难时：\n- 试着区分"他们的期待"和"我真正想要的"\n- 有些话题可以暂时回避，保护自己的边界\n- 找一个安全的人（朋友/老师/咨询师）倾诉\n- 记住：你可以选择爱他们，同时保持自己的独立性\n\n你和家人的主要矛盾是什么？是父母、伴侣还是其他家庭成员？', 14),
('父母', '和父母的关系可能是我们一生都在学习的课题。他们爱我们，但有时候方式让我们感到压力。\n\n几个思考角度：\n- 父母的很多行为来自他们自己的成长经历和焦虑\n- 你可以感恩他们的付出，同时拒绝不合理的要求\n- "孝顺"不等于"顺从"，你有权利追求自己想要的生活\n- 如果关系长期紧张，考虑家庭咨询\n\n父母让你感到压力的主要是什么方面？学业？工作？还是婚恋？', 15),
('生气', '生气是很正常的情绪，不是问题。问题是我们如何表达愤怒。\n\n健康地处理愤怒：\n- 先暂停：数到10，或者离开现场\n- 问自己："我真正在意的是什么？"
- 用"我"开头表达："我感到生气，因为..."\n- 运动是很好的发泄方式（跑步、打球、拳击）\n\n你现在为什么生气？说出来可能会好受一些。', 16),
('愤怒', '愤怒是一种信号，告诉你某些边界被侵犯了，或者某些需求没被满足。\n\n处理愤怒的策略：\n1. 先承认愤怒："是的，我很生气，这很正常"\n2. 找到愤怒的根源：是因为不公平？被忽视？还是害怕？\n3. 选择表达方式：写下来、运动、和信任的人聊聊\n4. 避免在愤怒时做重大决定\n\n愤怒本身没有错，错的是伤害自己或他人的表达方式。你想说说发生了什么吗？', 17),
('害怕', '害怕是一种保护机制，它在提醒我们某些事情可能有危险。\n\n面对恐惧：\n- 区分"真实的危险"和"想象的恐惧"\n- 如果是真实的，制定应对计划\n- 如果是想象的，问自己："最坏的结果是什么？我能承受吗？"
- 逐步暴露：从最不害怕的场景开始练习\n\n你在害怕什么？具体的事情，还是一种模糊的不安感？', 18),
('恐惧', '恐惧让我们想要逃避，但逃避往往会让恐惧变得更大。\n\n应对恐惧的方法：\n1. 深呼吸：恐惧时身体会紧张，深呼吸能激活副交感神经\n2. 事实检验：恐惧的想法有多少是真的？\n3. 小步前进：不需要一下子面对最大的恐惧\n4. 寻求支持：和朋友一起面对，或者找专业咨询师\n\n你最近有什么特别让你恐惧的事情吗？', 19),
('疲惫', '身心俱疲的时候，最重要的是允许自己休息。不是每个人都有条件"躺平"，但我们可以找到小的喘息空间。\n\n缓解疲劳：\n- 哪怕只有5分钟，闭上眼睛深呼吸\n- 中午小睡15-20分钟（不要超过30分钟）\n- 周末留出半天完全不安排任何事情\n- 检查：是不是在照顾所有人，唯独忘了照顾自己？\n\n你上次真正放松是什么时候？', 20),
('累', '累了就休息，这不是软弱，而是对自己负责。\n\n问自己几个问题：\n- 是身体累，还是心累？\n- 最近有没有好好吃饭、睡觉？\n- 有没有做一些让自己开心的事情？\n- 有没有人可以分担一些压力？\n\n有时候"累"是身体在提醒：该停下来，照顾自己了。你今天能为自己做一件小事吗？', 21),
('迷茫', '迷茫是因为站在人生的十字路口，不知道该往哪走。这其实说明你开始思考自己真正想要什么了——这是成长的表现。\n\n迷茫的时候：\n- 允许自己"不知道"，不需要立刻有答案\n- 写下你擅长的事、喜欢的事、在意的事\n- 和不同领域的人聊聊，了解更多的可能性\n- 先走一步试试看，路往往是走出来的\n\n你迷茫的是什么方面？职业？人生方向？还是感情？', 22),
('空虚', '空虚感常常出现在我们完成了别人期待的"成功"之后，却发现那不是自己真正想要的。\n\n填补空虚：\n- 问自己：如果没有别人的期待，我想做什么？\n- 尝试一件小而具体的事（做饭、种花、画画），投入其中\n- 建立真实的连接，和在意的人深聊一次\n- 做一次「WHO-5 幸福感指数」测评，看看生活中哪些部分让你感到有意义\n\n你觉得生活中缺少了什么？', 23),
('紧张', '紧张的时候身体会紧绷，这是战逃反应在启动。\n\n快速放松技巧：\n- 4-7-8呼吸：吸气4秒，屏住7秒，呼气8秒\n- 握紧拳头5秒，突然松开，感受放松的感觉\n- 冷水洗脸，或含一颗薄荷糖\n- 对自己说："我已经准备好了，我可以的"\n\n你现在是因为什么事情紧张？考试？面试？还是其他？', 24),
('担心', '担心是一种对未来的焦虑，它让我们反复想"如果...怎么办"。\n\n应对担心：\n- 写下来：你担心什么？最坏的结果是什么？你能做什么？\n- 区分"可控的"和"不可控的"，把精力放在可控的事情上\n- 设定"担心时间"：每天只允许自己担心15分钟\n- 问自己："这个担心，一个月后还重要吗？一年后呢？"\n\n你现在最担心的是什么？', 25),
('想哭', '想哭就哭吧，眼泪是身体在释放压力。很多研究表明，哭完后的情绪反而会变好。\n\n如果需要：\n- 找一个安全私密的空间\n- 准备纸巾和一杯温水\n- 哭完之后，洗个热水澡，或者吃点喜欢的东西\n- 把此刻的感受写下来\n\n你想哭是因为什么？如果愿意可以告诉我。', 26),
('考试', '考试焦虑是很多学生都会经历的。适度的紧张其实有助于发挥，但过度焦虑会影响表现。\n\n考前调节：\n- 考前一周调整作息，不要临时抱佛脚\n- 复习时重点看错题，不要再做新题\n- 考前一天晚上，就算睡不着也不要焦虑，闭目养神也有用\n- 进考场前做几次深呼吸\n\n你现在是焦虑到影响复习和睡眠了吗？', 27),
('面试', '面试紧张很正常，说明你在意这个机会。\n\n面试前准备：\n- 对着镜子练习自我介绍，注意语速和微笑\n- 准备几个常见问题的回答框架\n- 提前了解公司和岗位，准备2-3个问题问面试官\n- 穿让你感到自信的衣服\n\n记住：面试是双向选择，你也在考察这个公司是否适合你。你面试的是什么岗位？', 28),
('分手', '分手后的痛苦是真实的，就像戒断反应一样。大脑习惯了那个人的存在，突然断了连接会很痛苦。\n\n分手后的自我照顾：\n- 允许自己 grieving（哀悼），不需要"快点好起来"\n- 暂时不要联系对方，给彼此空间\n- 删掉或隐藏那些会触发回忆的东西\n- 重建生活：找回单身时喜欢做的事\n- 和朋友多在一起，哪怕不说话\n\n分手多久了？你还想复合，还是已经决定向前走了？', 29),
('无聊', '无聊不一定是坏事，它可能是你的内心在说："我想要一些新的刺激了"。\n\n应对无聊：\n- 尝试一件从未做过的小事（新的餐厅、新的路线）\n- 学习一个新技能，哪怕只是学做一道菜\n- 主动联系一个很久没联系的朋友\n- 做志愿者，帮助他人能带来意义感\n- 如果持续无聊且伴随情绪低落，可能是抑郁的信号\n\n你平时无聊的时候会做什么？', 30),
('自责', '自责往往来自于过高的自我要求。你可能对自己比对朋友还苛刻。\n\n换个角度：\n- 如果是你的朋友犯了这个"错误"，你会怎么安慰他？\n- 你对自己的批评，有多少是事实，有多少是想象？\n- 每个人都在学习和成长，包括你\n- 对自己说："我已经尽力了，这就够了"\n\n你在为什么事情自责？愿意说说吗？', 31),
('内疚', '内疚说明你是有良知的人，但过度的内疚会让你无法前进。\n\n处理内疚：\n- 问自己：这件事我是否真的有责任？\n- 如果确实有，道歉或补偿，然后放下\n- 如果过度内疚，试着区分"我的责任"和"别人的责任"\n- 对自己说："我允许自己犯错，我是人，不是神"\n\n你在内疚什么？是某件事，还是一种长期的自我否定？', 32),
('自卑', '自卑往往来自于和别人比较，或者把某个方面的不足当成了全部的自己。\n\n关于自卑的思考：\n- 你眼中的缺点，在别人看来可能根本不重要\n- 每个人都有不擅长的事，这很正常\n- 你的价值不是由某个技能或外貌决定的\n- 试着列出自己的3个优点，哪怕很小\n\n你觉得自己在哪方面自卑？外貌？能力？还是人际关系？', 33),
('社交恐惧', '社交恐惧不是"性格内向"，而是一种对社交场景的过度焦虑和回避。\n\n应对社交恐惧：\n- 从最小的社交开始：和便利店店员说"谢谢"\n- 准备几个万能话题（天气、美食、共同的课程/工作）\n- 降低期待：不需要让每个人都喜欢你\n- 如果严重影响生活，建议做「SPIN 社交恐惧量表」测评\n\n你在什么社交场景下最紧张？聚会？公开发言？还是日常聊天？', 34),
('拖延', '拖延不是懒，往往是情绪在逃避。\n\n理解拖延：\n- 完美主义：害怕做不好，所以不开始\n- 任务太大：不知道从哪开始\n- 缺乏动力：这件事对你来说不够重要\n- 即时满足：刷手机比工作更快乐\n\n应对拖延：\n- "先做2分钟"，开始后你会发现没那么难\n- 把大任务拆成可以5分钟完成的小块\n- 先完成再完美，第一稿总是糟糕的\n\n你拖延的是什么事情？学习？工作？还是其他？', 35),
('暴食', '暴食常常和情绪有关，而不是真的饿。食物有时候是我们处理情绪的一种方式。\n\n如果你经历暴食：\n- 不要自责，这不是意志力的问题\n- 试着记录：暴食前发生了什么？有什么情绪？\n- 找到替代方式：散步、洗澡、和朋友聊天\n- 如果需要，寻求营养师和心理咨询师的帮助\n\n暴食和厌食一样，都是饮食失调，需要被认真对待。你暴食的频率是怎样的？', 36),
('厌食', '厌食症是一种严重的心理健康问题，需要专业帮助。\n\n如果你或身边的人有厌食倾向：\n- 尽快寻求专业帮助（精神科医生 + 营养师 + 心理咨询师）\n- 不要独自面对，告诉信任的人\n- 记住：瘦不等于美，健康才是\n- 全国进食障碍求助热线：400-161-9995\n\n这不是你的错，也不是意志力的失败。你值得被好好照顾。请一定寻求专业帮助。', 37),
('噩梦', '噩梦常常反映了我们白天的焦虑和压力。\n\n减少噩梦：\n- 睡前1小时不看恐怖片/负面新闻\n- 睡前做放松练习（冥想、渐进式肌肉放松）\n- 如果噩梦反复出现同一个主题，可能是在提醒你某些需要面对的事情\n- 把噩梦写下来，然后改写一个更好的结局\n\n你经常做噩梦吗？噩梦的主题是什么？', 38),
('噩梦', '噩梦常常反映了我们白天的焦虑和压力。\n\n减少噩梦：\n- 睡前1小时不看恐怖片/负面新闻\n- 睡前做放松练习（冥想、渐进式肌肉放松）\n- 如果噩梦反复出现同一个主题，可能是在提醒你某些需要面对的事情\n- 把噩梦写下来，然后改写一个更好的结局\n\n你经常做噩梦吗？噩梦的主题是什么？', 39),
('疲惫', '身心俱疲的时候，最重要的是允许自己休息。不是每个人都有条件"躺平"，但我们可以找到小的喘息空间。\n\n缓解疲劳：\n- 哪怕只有5分钟，闭上眼睛深呼吸\n- 中午小睡15-20分钟（不要超过30分钟）\n- 周末留出半天完全不安排任何事情\n- 检查：是不是在照顾所有人，唯独忘了照顾自己？\n\n你上次真正放松是什么时候？', 40),
('强迫', '强迫思维和强迫行为是一种焦虑的表现，它们让你觉得"如果不做某事，就会发生不好的事情"。\n\n关于强迫：\n- 这不是你的错，也不是"想太多"\n- 对抗强迫的方式不是"不要想"，而是允许想法存在但不行动\n- 逐步减少强迫行为的频率\n- 如果严重影响生活，建议做「Y-BOCS 耶鲁布朗强迫量表」测评\n\n你有哪些强迫思维或行为？', 41),
('创伤', '创伤反应（闪回、噩梦、过度警觉）是大脑在经历危险后的正常保护机制。\n\n如果你经历过创伤：\n- 这不是你的错，也不是软弱\n- 创伤不会自动消失，需要时间和专业的帮助\n- EMDR（眼动脱敏与再加工）和创伤聚焦认知行为疗法被证实有效\n- 全国心理援助热线：400-161-9995\n\n你愿意说说你的经历吗？还是只是想了解一些信息？', 42),
('幻听', '幻听可能是一些精神健康问题的症状，需要认真对待。\n\n如果你或身边的人有幻听：\n- 不要惊慌，但要尽快寻求专业帮助\n- 去医院精神科做一个全面评估\n- 不要独自承受，告诉信任的人\n- 很多情况下，通过药物和心理治疗可以得到很好的控制\n\n这不是你的错。请尽快联系专业人士。全国心理援助热线：400-161-9995', 43),
('幻觉', '幻觉（看到/听到/感觉到不存在的东西）可能是精神健康问题的信号，需要专业评估。\n\n重要提醒：\n- 不要自责，这不是意志力的问题\n- 尽快去医院精神科就诊\n- 有些情况下，幻觉是由身体疾病（如高烧、脑部病变）引起的\n- 很多精神健康问题在早期干预下预后很好\n\n请务必寻求专业帮助。全国24小时心理援助热线：400-161-9995', 44),
('惊恐发作', '惊恐发作是非常可怕的经历，你会觉得心跳加速、呼吸困难、头晕，好像要死了。但请记住：惊恐发作不会导致死亡或发疯。\n\n惊恐发作时的应对：\n- 告诉自己："这是惊恐发作，我会没事的，它会过去的"\n- 用鼻吸气4秒，屏住4秒，用嘴呼气6秒\n- 找到一个稳定的物体（椅子、墙），感受它的坚实\n- 不要逃避，留在原地，让恐惧自然消退\n\n如果频繁发作，建议做「PDSS 惊恐障碍严重度量表」测评。你第一次发作是什么时候？', 45),
('panic', 'Panic attacks are very scary experiences, but please remember: panic attacks cannot cause death or insanity.\n\nDuring a panic attack:\n- Tell yourself: "This is a panic attack. I will be okay. It will pass."\n- Breathe in through your nose for 4 seconds, hold for 4 seconds, exhale through your mouth for 6 seconds\n- Find a stable object (chair, wall), feel its solidity\n- Do not escape. Stay where you are and let the fear naturally subside\n\nIf panic attacks occur frequently, consider taking the PDSS (Panic Disorder Severity Scale) assessment.', 46);

-- 验证插入结果
SELECT COUNT(*) AS total_keywords FROM psy_ai_words;
SELECT keyword, LEFT(reply_text, 50) AS preview FROM psy_ai_words ORDER BY sort LIMIT 10;
